From OSSVerify.Proofs.boost_beast.http_request.lib.Ref Require Import XP_isl3.
Section ISL_CLOSED.
  Context {HCEIL : HeapCeil}.
  Variable H : hsr.
  Hypothesis HH : heap_sr_hyps H.
  Hypothesis S2V : string_to_verb_stmt.
  Lemma isl_spec_req : isl_stmt H.
  Proof. exact (isl_spec H HH S2V (onreq_spec H HH S2V)). Qed.
End ISL_CLOSED.

